package com.galleryvote.submission;
import io.minio.*; import jakarta.annotation.PostConstruct; import java.io.*; import java.util.*; import javax.imageio.ImageIO; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException;
@Service public class StorageService {private static final Set<String>TYPES=Set.of("image/jpeg","image/png","image/gif","image/webp");private final MinioClient minio;private final String bucket;public StorageService(MinioClient m,@Value("${galleryvote.storage.bucket}")String b){minio=m;bucket=b;}
 @PostConstruct void bucket()throws Exception{if(!minio.bucketExists(BucketExistsArgs.builder().bucket(bucket).build()))minio.makeBucket(MakeBucketArgs.builder().bucket(bucket).build());}
 public String store(MultipartFile file){String type=Optional.ofNullable(file.getContentType()).orElse("").toLowerCase();if(file.isEmpty()||!TYPES.contains(type))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"JPEG, PNG, GIF, or WebP required");try{byte[] bytes=file.getBytes();if(ImageIO.read(new ByteArrayInputStream(bytes))==null)throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"Invalid image content");String key=UUID.randomUUID()+extension(type);minio.putObject(PutObjectArgs.builder().bucket(bucket).object(key).stream(new ByteArrayInputStream(bytes),bytes.length,-1).contentType(type).build());return key;}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Image storage unavailable",e);}}
 public byte[] read(String key){if(!key.matches("[0-9a-fA-F-]{36}\\.(jpg|png|gif|webp)"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid image key");try(var in=minio.getObject(GetObjectArgs.builder().bucket(bucket).object(key).build())){return in.readAllBytes();}catch(Exception e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Image not found",e);}}
 private String extension(String t){return switch(t){case "image/png"->".png";case "image/gif"->".gif";case "image/webp"->".webp";default->".jpg";};}}
